    "content_html": "<div class=\"text-center\">\r\n  <button type=\"button\" class=\"btn btn-light shadow-lg\">$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 64</span></button>\r\n</div><br/>",
