    "discipline": "Environmental",
    "subject": "Fluid Mechanics and Hydraulics",
    "chapter": "Dimensional Homogeneity",
    "topic": "Similitude",
    "subtopic": "Overview",
    "content_html": "<div class= \"container-fluid\">\r\n  <div class= \"row align-items-start\">\r\n    <div class=\"col-6\">\r\n   Here p = Prototype and m = Model\r\n\r\n<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$\\left[\\dfrac{F_I}{F_P}\\right]_p = \\left[\\dfrac{F_I}{F_P}\\right]_m = \\left[\\dfrac{\\rho v^2}{P}\\right]_p = \\left[\\dfrac{\\rho v^2}{P}\\right]_m$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 197</span></button>\r\n</div><br/>\r\n\r\n<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$[Re]_p = [Re]_m$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 197</span></button>\r\n</div><br/>\r\n\r\n<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$[Fr]_p = [Fr]_m$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 197</span></button>\r\n</div><br/>\r\n\r\n\r\n<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$[Ca]_p = [Ca]_m$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 197</span></button>\r\n</div><br/>\r\n\r\n\r\n\r\n<div class=\"text-center\">\r\n<button type=\"button\" class=\"btn btn-light shadow-lg\">$[We]_p = [Wb]_m$ <span class=\"text-muted\">&emsp; &emsp; &emsp; Page 197</span></button>\r\n</div><br/>\r\n    </div>\r\n    <div class=\"col\">\r\n<center><p><img src=\"https://upload.wikimedia.org/wikipedia/commons/c/c8/Similitude_%28model%29.png\" style=\"width:640px;\"></p>\r\n<small><small><a href=\"https://commons.wikimedia.org/wiki/File:Similitude_(model).png\">Duk</a>, <a href=\"http://creativecommons.org/licenses/by-sa/3.0/\">CC BY-SA 3.0</a>, via Wikimedia Commons</small></small></center><br/>\r\n    </div>\r\n  </div>\r\n</div>",
